      "三層觀察者的對照：「不懂行的人觀察一個事物，本能反應是看它的體量：這家公司資本真雄厚，這個組織成員真多，厲害！但是大並不等於健康。可能這家公司經營不善，都快要資不抵債了；那個組織人心已經散了。利益相關"
