      "framework": "嚴格定義（全講最重要的一段）：「零階道理，是在給定目標、時間尺度和比較對象之下，足以決定結論方向和主要量級的最小因果模型。」三個關鍵詞：方向（A 和 B 哪個好）、量級（好百分之一還是好十倍）、最小（只保留最少的幾個主導項，多一項都不要）。",
