    "keywords": "010 複利：可積累的優勢 可積累的優勢 複利的真正祕密不是利率高，而是持續時間長（巴菲特 vs 西蒙斯的對比；小張小李的定投思想實驗）。r（資本回報率）> g（勞動/經濟增長率，皮凱蒂）解釋了貧富差距的本質：富人的優勢可積累，打工掙錢不可積累。 提出七種值得積累複利的資本：金錢資本、人力資本、健康資本、社會資本、聲望資本、心理資本、體驗資本——彼此可以互相疊加轉化，形成正反饋飛輪。 ROI 意識 + 人生複利路線：18-25 抬利率期（重倉人力資本）、25-35 鎖賽道期（深耕+建聲望）、35-50 規模期（用槓桿放大）、50-65 抗衰/新探索期（壓縮經驗、外包瑣事）、65+ 分紅期。年輕的強是增長，中年的強是槓桿，老年的強是取捨。"
