    "keywords": "017 社交資本、結構洞和搬家：容易向上流動的位置 容易向上流動的位置 拉吉·切蒂的研究證明：出生在機會多的城市（如硅谷）比機會少的城市，向上流動概率高兩三倍；而且越早搬家越好，孩子更多是向周圍成年人學習而非向父母學習。 三種社會資本中，只有「經濟連通性」（跨階層交友）顯著預測窮人向上流動，「社會凝聚力」「公民參與度」幾乎無效；打破\"交友偏差\"最好靠共同任務（一起扛過槍、一起同過窗），而不是市儈式\"人脈\"。 「結構洞」（Ronald Burt）：站在兩個互不相連網路之間的\"經紀人\"位置，價值不在傳話而在翻譯/創造（鄧小平作爲紅區黨-白區黨結構洞的例子）。位置是命運的一部分，越是不利的位置，越要主動換位置。"
