    "tagline": "元認知黑魔法",
    "keywords": "020 身份認同：元認知黑魔法 元認知黑魔法 「身份認同」= 我是誰/人設/對人的定義權。它給人歸屬感、連貫感、可預測性，副作用是天然帶剛性——把身份當\"我\"就被驅使，把身份當\"我用的\"就能駕馭。經典案例\"Don't mess with Texas\"用重構身份敘事而非說教解決了亂扔垃圾問題。 借用凱根的「成人心智發展理論」五階段（衝動心智→帝王/工具心智→社會化心智→自我授權心智→自我轉化心智），只有 1% 的成年人到達最高階——能把身份當客體來審視和調用，而非被身份主體化驅使（主體-客體轉化）。 \"黑魔法\"的高階用法是同時設定別人的身份，甚至借用丹尼特的三種解釋立場（意向/設計/物理立場）剝離對方主體性以獲得情緒自由（把槓精當\"甲蟲\"而非\"辯論對手\"）。忠告：內核自我必須保持穩定，否則\"什麼都能理解，什麼都不再相信\"。"
