    "keywords": "021 安全感：人需要有所依靠 人需要有所依靠 安斯沃斯的陌生情境實驗：焦慮型依戀、迴避型依戀、安全型依戀——童年依戀類型會延續到成年後的婚戀、職場表現。人類的本能是尋求依靠而非尋求獨立。 安全感來自關係提供的兩個功能：「安全基地」（鼓勵你出去探索冒險）和「安全港灣」（接住你的失敗和脆弱）——基地鼓勵勇敢，港灣允許脆弱，最理想的關係兩者兼具。 安全感可以後天習得：覺察自己的依戀類型→成爲自己的安全港灣（自我關懷）→建立可控小環境→主動尋找外部盟友。谷歌\"亞裏士多德計劃\"發現團隊第一成功要素是「心理安全」，而非個人能力。被依賴，是當今世界給你最好的待遇。"
