    "keywords": "022 賽道選擇：做天兵天將，還是做孫悟空？ 做天兵天將，還是做孫悟空？ 「賽道選擇（Game Selection）」：選擇大於努力，因爲重尾世界是乘法遊戲，跟誰相乘比多努力更關鍵。天兵天將（體制內，遵循人際關係邏輯，地位靠分配）與孫悟空（體制外，遵循物理世界邏輯，地位靠自己創造）是兩種完全不同的遊戲，沒有高低之分，但混淆二者的心智會很慘。 天兵修行：把指標當工具而非人生，學會\"搞政治\"（政治技巧與晉升顯著正相關），但要警惕規則突變的系統性風險，最好悄悄修一個\"花果山副本\"（保留能耐尋求定理的多選項思維）。 孫悟空修行：練不對稱技能，用「利基構建」（主動創造生態位而非尋找現成崗位）和「效應化」（Effectuation，從手頭資源出發拼湊創新，而非先定目標找方案，\"打開冰箱看有什麼菜就做什麼飯\"）。問答（024）補充還有太上老君（借體制練自己的丹）、工匠（專業不可替代）、散仙（自由職"
