    "keywords": "025 探索與利用：怎樣繼續做個年輕人 怎樣繼續做個年輕人 借用「多臂老虎機問題」引出「探索（Explore）與利用（Exploit）的權衡」：先探索再利用（不能沒採樣就下注）；不能只探索不利用（該收網時收網，\"37% 法則\"/祕書問題）；哪怕已有不錯的可利用選項，只要時間允許也該繼續探索（邊際效益遞減）。數學最優解是「吉廷斯指數」：剩餘時間越長越該探索。 反直覺發現：從社會生活中退出會加速衰老（社交孤立→輸入減少→節能模式→更退出的惡性循環）；反過來，持續探索特別是\"真學習\"（而非刷手機式僞參與）能讓「超級老年人」的認知水平遠超實際年齡。 「連勝期（hot streak）」研究（王大順）：成功人士的模式是先探索多樣風格，捕捉到\"對了\"的感覺後轉向利用深耕出成績，然後再開啓新一輪探索——年輕不是皮膚狀態，而是系統更新的頻率；人們真正喜歡的也許不是年輕本身，而是探索。"
