    "tagline": "諸行無常，有偏置纔有決策",
    "keywords": "027 無免費午餐定理：諸行無常，有偏置纔有決策（模組開篇） 諸行無常，有偏置纔有決策 「無免費午餐定理（No Free Lunch Theorem, 1997, Wolpert & Macready）」：把所有可能問題平均起來看，任何兩個演算法的表現都一樣。你想在一個領域比別的演算法好，就必然在另一個領域比它差——AlphaGo 之所以下棋厲害，是因爲它偏科。你必須爲優化付出代價。 決策的元認知心法三步：① 強先驗（設定偏置，來源是價值觀 + 你對世界的基本假設）；② 演算法搜索（這一步必須極度理性客觀，尊重硬條件）；③ 系統化冒險。核心分野是「強偏置、弱偏執」——偏置是劍，偏執是枷鎖；老百姓要麼無偏置（優柔寡斷），要麼全偏執（一條道走到黑）。 萬維鋼的終極提法：「什麼都不做纔是最完美、最沒有偏見的狀態。偏見是你生命力的證明。」 AGI 時代人的核心價值就在於設定偏置。"
