    "tagline": "判斷是主觀的，但可以更科學一點",
    "keywords": "031 貝葉斯先驗：判斷是主觀的，但可以更科學一點 判斷是主觀的，但可以更科學一點 「先驗（prior）」就是你的成見——但成見是認知的起點，而且這個起點可以被量化、被更新、被審計。老百姓說「看法」，學者說「先驗」。 貝葉斯公式白話版：後驗 = 先驗 + 證據更新。罕見病例題（發病率 0.1%，檢測準確度 99%）的後驗只有 1/11——如果先驗原本很低，哪怕證據很強，把先驗提高一百倍，後驗也還是不高。這就是貝葉斯主義者的氣度。 兩種典型錯誤：① 完全沒有先驗（聽風就是雨不是謙遜，而是做人的不可預期）；② 先驗不可動搖（把概率設成 0 或 1）。「克倫威爾法則（Cromwell's Rule）」：真正的貝葉斯主義者永遠不會把概率設爲 0 或 1——「我懇求你們，想一想你們可能錯了。」"
