    "tagline": "怎樣區分沙子和金子",
    "keywords": "032 資訊價值：怎樣區分沙子和金子 怎樣區分沙子和金子 石油勘探經典案例：打井成本 1000 萬、有油值 5000 萬、有油概率 20%——不看報告的期望收益是 0，看了報告後期望價值是 800 萬，那麼這份地震波掃描報告的 VOI 就是 800 萬美元。對比之下，你昨晚看的那篇《萬字長文解析 AI 革命》，VOI 也許等於 0。沒有決策對象的資訊，其價 高價值資訊的三個特點：① 目標導向（且往往是本地的、專門對你的，而不是熱搜新聞）；② 帶有痛感（真正有價值的資訊一定不符合你原有認知模型，會改變你的先驗，因而讓你不舒服；對抗確認偏誤）；③ 出現在「決策邊界」上（你正好在兩個選項之間搖擺時，一條讓天平傾斜的資訊纔是高 VOI）。 「資訊價值（Value of Information, VOI）」理論（Howard, 1966）對價值的定義極其嚴格：只有當一條資訊能夠改變你的實際行動時，它纔有價值。VOI = 有這條資訊時你能做出的最佳選擇，比沒它時的最佳選擇，平均能多賺多少。"
