    "keywords": "033 凱利公式：乘法世界裏的認知變現 乘法世界裏的認知變現 「凱利公式（Kelly criterion）」1956 年出自貝爾實驗室的約翰·凱利，原本研究的是有噪聲電話線傳遞賽馬內幕消息該如何下注。結論極其優美：最佳下注比例 f\\* 之下，資金的最大長期對數增長率在數學上完全等同於這條電話線的「資訊傳輸率」——你的增長上限，受限於你的認知帶寬。 「凱利公式（Kelly criterion）」1956 年出自貝爾實驗室的約翰·凱利，原本研究的是有噪聲電話線傳遞賽馬內幕消息該如何下注。結論極其優美：最佳下注比例 f\\* 之下，資金的最大長期對數增長率在數學上完全等同於這條電話線的「資訊傳輸率」——你的增長上限，受限於你的認知帶寬。 「押太大和不敢押都是錯的。這不是資訊問題，這是倉位問題。」曹操評袁紹：「色厲膽薄，好謀無斷；幹大事而惜身，見小利而忘命」——建安五年田豐建議襲許都，那是巨大的 edge，袁紹卻因幼子生病而放棄。如果 edge 好，出手是一種義務。"
