    "keywords": "037 期權：保留可選項的特權 保留可選項的特權 老張租商鋪的故事：多付 20% 租金換來「一年後有權以鎖定價續租四年、不續租也無違約金」——如果局面你拿不準，有些事最好不要過早鎖定（commit），你可以給自己留一張期權。期權就是你的一個可選項：它只是權利，不是義務。 實驗 / MVP / 敏捷開發 = 看漲期權。傳統「瀑布式開發」是先鎖定再祈禱；「敏捷開發」把決策推遲到每一輪的「最後負責時刻（last responsible moment）」，是先學習再鎖定。試錯並不貴，最貴的是在無知時重倉；實驗不是爲了證明你對，而是爲了便宜地發現你錯。 最後的分辨：人們常常分不清「期權價值」和「實際價值」——聰明只是一種期權，若不能與執行力、情緒穩定、協作能力結合併轉化爲真實交付和信用，這張期權就無法兌現。而良好的社會關係本身就是實際價值（熟人是看跌期權，陌生人是看漲期權，兩種都該維護）。"
