    "keywords": "043 參考類：當局者迷，旁觀者清，你不特殊 當局者迷，旁觀者清，你不特殊 傅以斌的三步標準化流程：① 找一個數量足夠多、和你足夠相似而且已經結束的案例組（不是你喜歡的榜樣）；② 找出這個參考類的基準線（平均成本、時間、失敗率）；③ 把自己放進去對比微調。第三步最考驗人——最簡單的辦法是直接用中位數預測自己；如果你非要說自己不一樣，就必須有非常強硬的證據，不然你只是在把偏見 電影票房：2008–2012 年美國上映電影超過一半沒盈利，前 10% 喫掉近 70% 票房；2023 年基於 RCF 的隨機森林模型把「能否覆蓋成本」的預測準確度提到 90%。 精妙的補充：不是每個人都應該活成中位數——但如果你的天賦、資源和方法論真的特殊到不屬於當前參考類，那你也不能聽內部敘事，你屬於下一個參考類。總結：具體做事，不妨用內部敘事給自己打氣；決策，卻必須用外部參考類給自己潑冷水。"
