    "keywords": "044 超級預測：給不確定性命名，給自己打分 給不確定性命名，給自己打分 泰特洛克用二十多年追蹤 284 位專家的八萬多條預測，發現專家的準確度還不如最簡單的統計演算法、有時連黑猩猩都不如。《專家的政治判斷》借柏林的比喻分兩類：「刺蝟型」專家知道一件大事（抱着一套大理論解釋世界，易陷一廂情願）；「狐狸型」專家知道很多小事（接受複雜度、考慮多線索、隨時修正），後者更準。 示範例題（「我搬去廣州能幸福嗎」）：把「幸福」費米化爲工作、居住、婚戀、生活適應四個維度；以工作爲例——「3 個月內找到月薪不低於現在 80% 的工作」，獵頭數據給出 40% 的參考類基準 → 考慮核心專利與前同事內推上調到 65% → 一週後拿到兩個面試再貝葉斯更新到 74%。你的決策將不再是人格宣言，更不是豪賭。然後別忘了事後記分復盤——研究表明哪怕是短 概率化三步：① 費米化（Fermi-izing）——把邊界模糊、無法直接判定對錯的「雲狀問題」（如「中美會不會脫鉤」）拆成可操作的小問題（「未來六個月內某關稅法案通過的概率是多少」）；② 用外部視角打底（參考類基礎比率），用內部視角微調；③ 貝葉斯更新——利好從 43% 調到 4"
