    "tagline": "不是反應快，而是換腦快",
    "keywords": "045 OODA 環：不是反應快，而是換腦快（模組收官） 不是反應快，而是換腦快 更深的一層：要點不在於你的循環比對方快，而在於你的循環有效——最好你還能誤導對方的循環。拳擊案例中，乙不是贏在最後那一拳，而是贏在他誤導了甲 OODA 中的「定向」那一步，把甲的腦子帶進了錯誤地圖。 與前面模組的連接：OODA 就是「預測加工（predictive processing）」和自由能原理中「主動推斷（active inference）」的行動版——不是先把世界看清楚再行動，而是帶着模型行動，用行動去採樣世界。博伊德後期把 D 更多解釋爲「假設（Hypothesis）」、把 A 更多解釋爲對世界的一次「壓力測試（Stress Test）」。廣 「OODA 環（OODA Loop）」= 觀察—定向—決策—行動（Observe–Orient–Decide–Act）的循環，1970 年代由美國空軍傳奇飛行員博伊德（John Boyd）提出（他常打 40 美元的賭，說能從劣勢位置在 40 秒內翻到對手後方完成反殺）。"
